1	import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
2	import { existsSync, readFileSync, statSync } from "node:fs";
3	import { extname, resolve, sep } from "node:path";
4	import { Group } from "@semaphore-protocol/group";
5	import { verifyProof, type SemaphoreProof } from "@semaphore-protocol/proof";
6	import { openCatalog } from "./store.ts";
7	import { isProofPayload, terminateProverWorkers, textToField } from "./voting.ts";
8	
9	const MAX_BODY_BYTES = 1_000_000;
10	
11	function readBody(request: IncomingMessage): Promise<string> {
12	  return new Promise((resolvePromise, rejectPromise) => {
13	    const chunks: Buffer[] = [];
14	    let size = 0;
15	    request.on("data", (chunk: Buffer) => {
16	      size += chunk.length;
17	      if (size > MAX_BODY_BYTES) { rejectPromise(new Error("body_too_large")); request.destroy(); return; }
18	      chunks.push(chunk);
19	    });
20	    request.on("end", () => resolvePromise(Buffer.concat(chunks).toString("utf8")));
21	    request.on("error", rejectPromise);
22	  });
23	}
24	
25	export function createApp(databasePath: string, publicPath = resolve("dist/public")) {
26	  const catalog = openCatalog(databasePath);
27	  let proverUsed = false;
28	  const mime: Record<string, string> = { ".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".css": "text/css; charset=utf-8", ".svg": "image/svg+xml", ".json": "application/json; charset=utf-8" };
29	  const server = createServer((request, response) => {
30	    handle(request, response).catch(() => {
31	      if (!response.headersSent) response.writeHead(500, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" });
32	      response.end(JSON.stringify({ error: "internal_error" }));
33	    });
34	  });
35	  server.on("close", () => {
36	    catalog.close();
37	    // Release the snarkjs worker pool so the process can exit.
38	    if (proverUsed) void terminateProverWorkers();
39	  });
40	  return server;
41	
42	  async function handle(request: IncomingMessage, response: ServerResponse) {
43	    function json(status: number, payload: unknown, headers: Record<string, string> = {}) {
44	      response.writeHead(status, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", ...headers });
45	      response.end(JSON.stringify(payload));
46	    }
47	    const url = new URL(request.url ?? "/", "http://localhost");
48	    const segments = url.pathname.split("/").filter(Boolean);
49	    if (segments[0] === "api") {
50	      const method = request.method ?? "GET";
51	      if (url.pathname === "/api/health") {
52	        if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
53	        return json(200, { service: "veilvote", status: "ok" });
54	      }
55	      if (segments[1] === "polls" && segments.length <= 4) {
56	        if (segments.length === 2) {
57	          if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
58	          return json(200, { polls: catalog.list() });
59	        }
60	        let id: string;
61	        try { id = decodeURIComponent(segments[2]); }
62	        catch { return json(400, { error: "invalid_poll_id" }); }
63	        if (segments.length === 3) {
64	          if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
65	          const poll = catalog.get(id);
66	          return poll ? json(200, { poll }) : json(404, { error: "poll_not_found" });
67	        }
68	        if (segments[3] === "results") {
69	          if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
70	          const result = catalog.results(id);
71	          return result ? json(200, { result }) : json(404, { error: "poll_not_found" });
72	        }
73	        if (segments[3] === "votes") {
74	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
75	          const poll = catalog.get(id);
76	          if (!poll) return json(404, { error: "poll_not_found" });
77	          let body: unknown;
78	          try { body = JSON.parse(await readBody(request)); }
79	          catch { return json(400, { error: "invalid_json" }); }
80	          if (typeof body !== "object" || body === null) return json(400, { error: "invalid_vote" });
81	          const { optionId, proof } = body as { optionId?: unknown; proof?: unknown };
82	          if (typeof optionId !== "string" || optionId.length === 0 || !isProofPayload(proof)) {
83	            return json(400, { error: "invalid_vote" });
84	          }
85	          if (!poll.options.some(option => option.id === optionId)) return json(400, { error: "unknown_option" });
86	          if (poll.status !== "open" || Date.now() >= Date.parse(poll.closesAt)) return json(409, { error: "poll_closed" });
87	          // The proof must be bound to this poll (scope), the chosen option
88	          // (message) and the current member tree (root) rebuilt from SQLite.
89	          const group = new Group(catalog.memberCommitments());
90	          let bound = false;
91	          try {
92	            bound =
93	              proof.scope === textToField(poll.id) &&
94	              proof.message === textToField(optionId) &&
95	              proof.merkleTreeRoot === group.root.toString();
96	          } catch { bound = false; }
97	          if (!bound) return json(422, { error: "proof_binding_mismatch" });
98	          let valid = false;
99	          proverUsed = true;
100	          try { valid = await verifyProof(proof as unknown as SemaphoreProof); }
101	          catch { valid = false; }
102	          if (!valid) return json(422, { error: "invalid_proof" });
103	          const outcome = catalog.commitVote(poll.id, optionId, proof.nullifier);
104	          if (!outcome.ok) {
105	            if (outcome.reason === "duplicate_nullifier") return json(409, { error: "duplicate_nullifier" });
106	            if (outcome.reason === "poll_closed") return json(409, { error: "poll_closed" });
107	            return json(400, { error: "unknown_option" });
108	          }
109	          return json(201, { receipt: outcome.receipt });
110	        }
111	      }
112	      if (segments[1] === "receipts" && segments.length === 3) {
113	        if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
114	        let id: string;
115	        try { id = decodeURIComponent(segments[2]); }
116	        catch { return json(400, { error: "invalid_receipt_id" }); }
117	        const receipt = catalog.receipt(id);
118	        return receipt ? json(200, { receipt }) : json(404, { error: "receipt_not_found" });
119	      }
120	      return json(404, { error: "not_found" });
121	    }
122	    if (request.method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
123	    let relativePath: string;
124	    try { relativePath = decodeURIComponent(url.pathname); }
125	    catch { return json(400, { error: "invalid_path" }); }
126	    const file = resolve(publicPath, relativePath === "/" ? "index.html" : `.${relativePath}`);
127	    if (!file.startsWith(`${resolve(publicPath)}${sep}`) || !existsSync(file) || !statSync(file).isFile()) return json(404, { error: "not_found" });
128	    response.writeHead(200, { "Content-Type": mime[extname(file)] ?? "application/octet-stream", "X-Content-Type-Options": "nosniff" });
129	    response.end(readFileSync(file));
130	  }
131	}
