15	function date(value: string) { return new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "long", day: "numeric", timeZone: "Asia/Shanghai" }).format(new Date(value)); }
16	async function request<T>(path: string, init?: RequestInit): Promise<T> {
17	  const response = await fetch(path, init);
18	  if (!response.ok) throw Object.assign(new Error(`请求失败（${response.status}）`), { status: response.status, body: await response.json().catch(() => undefined) });
19	  return response.json() as Promise<T>;
20	}
