22	const ERROR_TEXT: Record<string, string> = {
23	  poll_closed: "议题已截止，无法投票",
24	  duplicate_nullifier: "该身份已在此议题投过票（重复提交被拒绝）",
25	  invalid_proof: "证明无效，投票被拒绝",
