52	  section.append(text("h3", "匿名投票"));
53	  section.append(text("p", "身份秘密仅在本页内存中用于生成 Semaphore 零知识证明，不会上传、保存或离开浏览器。演示身份 veilvote-demo-member-01 至 veilvote-demo-member-08 仅供合成演示数据，不可用于真实用户。", "muted vote-note"));
54	
55	  const identityLabel = text("label", "身份秘密", "vote-label");
56	  const identityInput = document.createElement("input");
57	  identityInput.type = "password";
58	  identityInput.autocomplete = "off";
59	  identityInput.placeholder = "演示：veilvote-demo-member-01";
60	  identityLabel.append(identityInput);
61	
62	  const optionFieldset = document.createElement("fieldset");
63	  optionFieldset.className = "vote-options";
64	  const legend = text("legend", "选择方案");
