69	    radio.type = "radio";
70	    radio.name = "vote-option";
71	    radio.value = option.id;
72	    if (index === 0) radio.checked = true;
73	    label.append(radio, text("span", option.label));
74	    optionFieldset.append(label);
75	  });
76	
77	  const submit = document.createElement("button");
78	  submit.type = "button";
79	  submit.className = "vote-submit";
80	  submit.textContent = "生成证明并提交选票";
81	  const status = text("p", "", "vote-status");
82	  status.setAttribute("aria-live", "polite");
