84	  const resultsMount = text("div", "", "results-mount");
85	
86	  async function refreshResults() {
87	    try {
88	      const { result } = await request<{ result: PollResults }>(`/api/polls/${encodeURIComponent(poll.id)}/results`);
89	      resultsMount.replaceChildren(resultsBlock(result, poll));
