91	  }
92	
93	  let busy = false;
94	  submit.addEventListener("click", async () => {
95	    if (busy) return;
96	    const secret = identityInput.value.trim();
97	    const optionId = optionFieldset.querySelector<HTMLInputElement>("input:checked")?.value;
98	    if (!secret) { status.textContent = "请输入身份秘密。"; status.className = "vote-status error"; return; }
99	    if (!optionId) { status.textContent = "请选择一个方案。"; status.className = "vote-status error"; return; }
100	    busy = true;
101	    submit.disabled = true;
102	    receiptBox.replaceChildren();
103	    try {
104	      status.textContent = "正在生成身份与分组…";
105	      status.className = "vote-status";
