107	        import("@semaphore-protocol/identity"),
108	        import("@semaphore-protocol/group"),
109	        import("@semaphore-protocol/proof")
110	      ]);
111	      const identity = new Identity(secret);
112	      if (!poll.eligibleMemberCommitments.includes(identity.commitment.toString())) {
113	        throw new Error("该身份不在本议题的成员承诺中，请检查输入。");
114	      }
115	      const group = new Group(poll.eligibleMemberCommitments);
116	      status.textContent = "正在生成零知识证明（首次需下载证明参数）…";
117	      const proof = await generateProof(identity, group, optionId, poll.id);
118	      status.textContent = "正在提交选票…";
119	      const { receipt } = await request<{ receipt: VoteReceipt }>(`/api/polls/${encodeURIComponent(poll.id)}/votes`, {
120	        method: "POST",
121	        headers: { "Content-Type": "application/json" },
122	        body: JSON.stringify({ optionId, proof })
123	      });
124	      identityInput.value = "";
