182	    button.append(text("span", poll.organizer, "card-organizer"), text("strong", poll.title), text("span", poll.summary, "card-summary"), text("span", `${poll.memberCount} 位成员 · ${poll.optionCount} 个方案`, "card-meta"));
183	    button.addEventListener("click", () => void showPoll(poll.id)); list.append(button);
184	  });
185	  if (polls[0]) await showPoll(polls[0].id); else list.append(text("p", "暂无议题"));
186	} catch (error) { list.replaceChildren(text("p", error instanceof Error ? error.message : "目录暂时不可用", "error")); }
