  else if (operation === "rotate" && isCommitment(oldCommitment) && isCommitment(newCommitment)) op = { type: "rotate", oldCommitment, newCommitment };
  else if (operation === "revoke" && isCommitment(commitment)) op = { type: "revoke", commitment };
  else return json(400, { error: "invalid_group_operation" });
  const outcome = catalog.applyGroupOperation(id, op, expectedVersion);
