    const options = JSON.stringify([{ id: "yes", label: "Yes" }, { id: "no", label: "No" }]);
    const insertPoll = db.prepare("INSERT INTO polls VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");
